CREATE TABLE IF NOT EXISTS gis_identity_crosswalk_certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, version text NOT NULL, total_features integer NOT NULL, certified_features integer NOT NULL DEFAULT 0, review_required integer NOT NULL DEFAULT 0, rejected_features integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'BLOCKED', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_code,version));